const DEFAULT_WORKING_DIR: &str = "./working";
/// Default cap on model turns per request. Effectively unlimited: a sane
/// upper bound so runaway tool-call loops still terminate, but far above any
/// realistic working session.
const DEFAULT_MAX_TURNS: usize = 1000;
/// Default cap on model turns in task mode (long-horizon self-improvement).
const TASK_MAX_TURNS: usize = 1000;

#[derive(Parser, Debug)]
#[command(
    name = "hānihi",
    version,
    about = "Rust agent harness: rig + rmcp + reedline"
)]
struct Args {
    /// OpenAI-compatible chat completions base URL.
    #[arg(
	long,
	env = "LLM_BASE_URL",
	default_value = "https://api.deepseek.com/v1"
    )]
    base_url: String,

    /// API key (or set LLM_API_KEY).
    #[arg(long, env = "LLM_API_KEY")]
    api_key: Option<String>,

    /// Model name (or set LLM_MODEL).
    #[arg(long, env = "LLM_MODEL", default_value = "deepseek-chat")]
    model: String,

    /// Working directory for sessions (default: ./working, relative to cwd).
    #[arg(long, env = "HANIHI_WORKING_DIR", default_value = DEFAULT_WORKING_DIR)]
    working_dir: PathBuf,

    /// Use an existing session by name (default: "default-session").
    #[arg(long, default_value = "default-session")]
    session: String,

    /// Create a new session with this name and use it.
    #[arg(long, conflicts_with = "session")]
    new_session: Option<String>,

    /// MCP stdio server command(s) to attach, e.g.
    /// `--mcp-command "./target/debug/mcp-echo-server"`. May be repeated.
    #[arg(long = "mcp-command", value_name = "CMD")]
    mcp_commands: Vec<String>,

    /// Run a single turn and exit (no REPL).
    #[arg(long, value_name = "PROMPT")]
    once: Option<String>,

    /// Register write tools (apply_patch, write_file) — enables editing the
    /// enclosing repository. Off by default; analysis and build tools are
    /// always on.
    #[arg(long)]
    write: bool,

    /// Run a single long-horizon turn with the task-mode system prompt
    /// (workflow gates: fmt → test → build → clippy → commit). Takes
    /// precedence over --once.
    #[arg(long, value_name = "PROMPT")]
    task: Option<String>,

    /// Maximum model turns per request (default: 1000; task mode: 1000).
    #[arg(long)]
    max_turns: Option<usize>,

    /// Append this text to the system prompt. Repeatable. When used with an
    /// existing session, the appended text is persisted to the session so it
    /// applies on future resumes too.
    #[arg(long = "prompt", value_name = "TEXT")]
    prompt_append: Vec<String>,

    /// Append the content of this file to the system prompt. Repeatable.
    /// When used with an existing session, the appended content is persisted
    /// to the session so it applies on future resumes too.
    #[arg(long = "prompt-file", value_name = "PATH")]
    prompt_files: Vec<PathBuf>,

    /// Replace the entire system prompt with the additions (no base prompt
    /// is prepended). For use with --session to rewrite the stored prompt,
    /// or with --new-session to override the default. Mutually exclusive
    /// with --prompt/--prompt-file append semantics (see below).
    #[arg(long)]
    new_prompt: bool,
}

/// Extract a short provider name from a base URL hostname.
fn provider_from_url(url: &str) -> &str {
    // Strip scheme.
    let host = url
	.trim_start_matches("https://")
	.trim_start_matches("http://")
	.split('/')
	.next()
	.unwrap_or("unknown");
    // e.g. "api.deepseek.com" -> "deepseek", "api.openai.com" -> "openai"
    host.trim_start_matches("api.")
	.trim_start_matches("api-")
	.split('.')
	.next()
	.unwrap_or("unknown")
}

/// Read the given prompt files and return their concatenated contents.
fn read_prompt_files(paths: &[PathBuf]) -> Result<String, AgentError> {
    let mut out = String::new();
    for path in paths {
	let content = fs::read_to_string(path)?;
	if !out.is_empty() {
	    out.push('\n');
	}
	out.push_str(&content);
    }
    Ok(out)
}

/// Read a single file's contents for use as a prompt, resolved against the
/// given base directory when the path is not absolute.
fn read_prompt_file(base: &Path, path: &str) -> Result<String, AgentError> {
    let resolved = if Path::new(path).is_absolute() {
	PathBuf::from(path)
    } else {
	base.join(path)
    };
    eprintln!("{}:{}: Path to resolve: {resolved:?}", file!(), line!());
    if !resolved.is_file() {
	return Err(AgentError::Io(std::io::Error::new(
	    std::io::ErrorKind::NotFound,
	    format!("no such file: {}", resolved.display()),
	)));
    }
    fs::read_to_string(&resolved).map_err(AgentError::Io)
}

/// Concatenate the explicit additions (`--prompt` strings and the contents
/// of `--prompt-file` files) into one block.
fn collect_extras(
    prompt_appends: &[String],
    prompt_files: &[PathBuf],
) -> Result<String, AgentError> {
    let file_text = read_prompt_files(prompt_files)?;
    let mut parts: Vec<String> = Vec::new();
    parts.extend(prompt_appends.iter().cloned());
    if !file_text.is_empty() {
	parts.push(file_text);
    }
    Ok(parts.join("\n\n"))
}

/// Whether any explicit prompt additions were supplied.
fn has_extras(prompt_appends: &[String], prompt_files: &[PathBuf]) -> bool {
    !prompt_appends.is_empty() || !prompt_files.is_empty()
}

/// Read the system prompt stored in an existing session's session.json.
fn stored_session_prompt(working_dir: &std::path::Path, session_name: &str) -> Option<String> {
    let meta_path = working_dir
	.join("sessions")
	.join(session_name)
	.join("session.json");
    let bytes = fs::read_to_string(meta_path).ok()?;
    let meta: serde_json::Value = serde_json::from_str(&bytes).ok()?;
    meta.get("system_prompt")
	.and_then(|v| v.as_str())
	.map(|s| s.to_string())
}

/// Persist a system prompt into an existing session's session.json. Reads
/// the file, updates the field, writes it back.
fn write_session_prompt(
    working_dir: &std::path::Path,
    session_name: &str,
    prompt: &str,
) -> Result<(), AgentError> {
    let meta_path = working_dir
	.join("sessions")
	.join(session_name)
	.join("session.json");
    let bytes = fs::read(&meta_path).map_err(AgentError::Io)?;
    let mut meta: serde_json::Value = serde_json::from_slice(&bytes).map_err(AgentError::Json)?;
    meta["system_prompt"] = serde_json::Value::String(prompt.to_string());
    fs::write(&meta_path, serde_json::to_string_pretty(&meta)?).map_err(AgentError::Io)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), AgentError> {
    tracing_subscriber::fmt()
	.with_env_filter(
	    EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
	)
	.init();

    let args = Args::parse();
    let api_key = args
	.api_key
	.filter(|k| !k.is_empty())
	.ok_or(AgentError::MissingApiKey)?;

    // Resolve working directory relative to cwd.
    let working_dir = if args.working_dir.is_absolute() {
	args.working_dir.clone()
    } else {
	std::env::current_dir()?.join(&args.working_dir)
    };

    let mut mgr = SessionManager::new(&working_dir);
    let provider = provider_from_url(&args.base_url);

    let task_mode = args.task.is_some();
    let base_prompt: &str = if task_mode {
	hanihi_core::agent::TASK_SYSTEM_PROMPT
    } else {
	hanihi_core::agent::DEFAULT_SYSTEM_PROMPT
    };

    // Determine session name and whether to auto-create.
    let (session_name, is_new) = if let Some(ref name) = args.new_session {
	(name.clone(), true)
    } else {
	let name = args.session.clone();
	// Auto-create default-session if it doesn't exist.
	let is_new = name == "default-session" && !mgr.exists(&name);
	(name, is_new)
    };

    let had_extras = has_extras(&args.prompt_append, &args.prompt_files);

    // Resolve the system prompt this invocation will use, and whether it
    // must be persisted back to the session's metadata.
    //
    // Prompt resolution rules:
    //  - `--new-prompt` on any session: the additions (collected from
    //    --prompt / --prompt-file) become the ENTIRE prompt. On an existing
    //    session this replaces and persists the stored prompt.
    //  - Otherwise `--prompt` / `--prompt-file` append to the base prompt
    //    (new session) or to the stored prompt (existing session), and the
    //    appended result is persisted so it survives a resume.
    //  - With no additions at all, the existing stored prompt is used
    //    unchanged (or the base prompt for a fresh session).
    let (session_prompt, do_persist) = if args.new_prompt {
	// Replace/set the entire prompt from the additions only.
	let prompt = collect_extras(&args.prompt_append, &args.prompt_files)?;
	let effective = if prompt.trim().is_empty() {
	    // --new-prompt with nothing supplied: use base as the new prompt.
	    base_prompt.to_string()
	} else {
	    prompt
	};
	if is_new {
	    (effective, false) // creation persists it
	} else {
	    (effective, true) // replace + persist the stored prompt
	}
    } else if is_new {
	// Fresh session: base + any appends. persisted by creation.
	let prompt = if had_extras {
	    let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
	    format!("{base_prompt}\n\n{extras}")
	} else {
	    base_prompt.to_string()
	};
	(prompt, false)
    } else if had_extras {
	// Existing session with appends: stored + extras, persisted.
	let stored = stored_session_prompt(&working_dir, &session_name)
	    .unwrap_or_else(|| base_prompt.to_string());
	let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
	let prompt = format!("{stored}\n\n{extras}");
	(prompt, true)
    } else {
	// Existing session, no additions: use stored prompt unchanged.
	let stored = stored_session_prompt(&working_dir, &session_name)
	    .unwrap_or_else(|| base_prompt.to_string());
	(stored, false)
    };

    // Create or open the session.
    if is_new {
	if session_name == "default-session" {
	    mgr.create_default(&args.model, &session_prompt)
		.map_err(|e| AgentError::Rig(e.to_string()))?;
	    println!("auto-created session 'default-session'");
	} else {
	    mgr.create(&session_name, &args.model, &session_prompt)
		.map_err(|e| AgentError::Rig(e.to_string()))?;
	    println!("created session '{session_name}'");
	}
    } else {
	mgr.open(&session_name)
	    .map_err(|e| AgentError::Rig(e.to_string()))?;
	if do_persist {
	    write_session_prompt(&working_dir, &session_name, &session_prompt)?;
	    if args.new_prompt {
		println!("session '{session_name}' system prompt replaced");
	    } else {
		println!("session '{session_name}' system prompt extended");
	    }
	}
    }

    // Build the agent with the resolved system prompt.
    let mut agent = connect_chat_model_with_prompt(
	args.base_url.clone(),
	api_key.clone(),
	args.model.clone(),
	&session_prompt,
    )?;
    agent.set_max_turns(args.max_turns.unwrap_or(if task_mode {
	TASK_MAX_TURNS
    } else {
	DEFAULT_MAX_TURNS
    }));
    agent.add_tool(builtin_get_time());
    agent.add_tool(builtin_echo());

    // Source-tree tools: read/list/grep/run-command over the enclosing git
    // repository, plus a window into this session's own event log. Ignore
    // rules (.gitignore, .ignore) filter what the agent can see. Write tools
    // (apply_patch, write_file) are registered only with --write.
    match SourceTree::open() {
	Ok(tree) => {
	    let tree = Arc::new(tree);
	    let traces_dir = working_dir.join("traces").join(&session_name);
	    let log_path = working_dir
		.join("sessions")
		.join(&session_name)
		.join("events.jsonl");
	    agent.add_tool(builtin_read_file(tree.clone()));
	    agent.add_tool(builtin_list_dir(tree.clone()));
	    agent.add_tool(builtin_grep(tree.clone()));
	    agent.add_tool(builtin_run_command(tree.clone(), traces_dir));
	    agent.add_tool(builtin_read_session_log(log_path));
	    if args.write {
		agent.add_tool(builtin_apply_patch(tree.clone()));
		agent.add_tool(builtin_write_file(tree));
	    }
	}
	Err(e) => println!("source tools disabled (no git repository): {e}"),
    }

    for command in &args.mcp_commands {
	let parts: Vec<String> = command.split_whitespace().map(String::from).collect();
	let (program, rest) = parts.split_first().ok_or_else(|| AgentError::Tool {
	    name: "<mcp>".into(),
	    message: "empty --mcp-command".into(),
	})?;
	let client = McpClient::connect_stdio(program, rest).await?;
	let tools = client.tool_defs().await?;
	let count = tools.len();
	for tool in tools {
	    agent.add_tool(tool);
	}
	println!("attached MCP server '{program}': {count} tool(s)");
    }

    // Get a mutable reference to the open session so we can read its turn
    // count for the "session renewed" metadata below.
    let session = mgr
	.open(&session_name)
	.map_err(|_e| AgentError::Rig("failed to re-open session".into()))?;

    // Replay prior turns from the event log so the agent remembers
    // previous conversations in this session.
    let mut prior_turns = None;
    match session.replay_history() {
	Ok(history) if !history.is_empty() => {
	    let msg_count = history.len();
	    agent.set_history(history);
	    println!("replayed {msg_count} messages from prior session");
	}
	Ok(_) => {} // empty history, nothing to replay
	Err(e) => {
	    tracing::warn!("failed to replay session history: {e}");
	}
    }
    // How many turns has this session accumulated so far (including from
    // prior sessions)? Use the session's own counter; it is monotonically
    // increasing across restarts of the same session name.
    if let Ok(turns) = session.total_turns() {
	prior_turns = Some(turns);
    }

    println!(
	"agent ready: model={} tools={} session='{session_name}' max_turns={}{}",
	args.model,
	agent.tool_count(),
	agent.max_turns(),
	if args.write {
	    " (write tools enabled)"
	} else {
	    ""
	},
    );
    if let Some(t) = prior_turns {
	println!(
	    "session '{}' renewed: total turns so far = {t}",
	    session_name
	);
    }
    println!("system prompt: {} bytes", session_prompt.len());

    let prompt = args.task.clone().or_else(|| args.once.clone());
    if let Some(prompt) = prompt {
	let mut rx = session
	    .run_streaming(&mut agent, provider, &args.model, &prompt)
	    .await
	    .map_err(|e| AgentError::Rig(e.to_string()))?;

	while let Some(event) = rx.recv().await {
	    match event {
		StreamEvent::TextDelta { text } => print_coloured!("{text}"),
		StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
		StreamEvent::ToolCallArgs { .. } => {}
		StreamEvent::ToolCallReady { .. } => {}
		StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
		StreamEvent::TurnComplete { summary } => {
		    println!();
		    println_coloured!(
			"[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
			session.turn,
			summary.tool_calls,
			summary.usage.input_tokens,
			summary.usage.output_tokens,
			agent.max_turns()
		    );
		    agent.set_history(summary.final_history);
		    break;
		}
		StreamEvent::Error { message } => {
		    eprintln!();
		    eprintln!("error: {message}");
		    break;
		}
	    }
	}
	mgr.close(&session_name)
	    .map_err(|e| AgentError::Rig(e.to_string()))?;
	return Ok(());
    }

    let cwd = std::env::current_dir().map_err(AgentError::Io)?;
    repl(session, agent, provider, &args.model, &cwd, &working_dir).await?;

    mgr.close(&session_name)
	.map_err(|e| AgentError::Rig(e.to_string()))?;
    Ok(())
}

/// Render the per-turn completion footer shown after (and by /session for) a turn.
fn turn_footer(
    turn: u64,
    tool_calls: usize,
    tokens_in: u64,
    tokens_out: u64,
    max_turns: usize,
) -> String {
    format!(
	"[turn {turn} | tool calls: {tool_calls} | tokens: {tokens_in} in / {tokens_out} out | max_turns: {max_turns}]"
    )
}

/// Interactive readline loop.
async fn repl<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    mut agent: Agent<M>,
    provider: &str,
    model_name: &str,
    cwd: &Path,
    working_dir: &Path,
) -> Result<(), AgentError> {
    let history_path = session.root().join("history.txt");
    let history: Box<dyn reedline::History> =
	match FileBackedHistory::with_file(10_000, history_path) {
	    Ok(h) => Box::new(h),
	    Err(e) => {
		eprintln!("history file disabled: {e}");
		Box::new(FileBackedHistory::new(10_000).expect("in-memory history"))
	    }
	};
    let edit_mode = reedline::Emacs::default();
    let mut editor = Reedline::create()
	.with_edit_mode(Box::new(edit_mode))
	.with_history(history)
	.with_highlighter(Box::new(MonoHighlighter::new(Color::Cyan)));
    let prompt = DefaultPrompt::default();
    let mut last_summary: Option<TurnSummary> = None;
    loop {
	match editor.read_line(&prompt) {
	    Ok(Signal::Success(line) | Signal::HostCommand(line)) => {
		let line = line.trim().to_string();
		match line.as_str() {
		    "" => continue,
		    "/quit" | "/exit" => break,
		    "/help" => {
			println!(
			    "commands: /help /tools /clear /session /file /quit — anything else is sent to the model"
			);
			continue;
		    }
		    "/tools" => {
			for def in agent.tool_definitions() {
			    println!("- {}: {}", def.name, def.description);
			}
			continue;
		    }
		    "/clear" => {
			agent.clear_history();
			println!("history cleared");
			continue;
		    }
		    "/session" => {
			println!(
			    "session: '{}' (id={}) turn={} max_turns={}",
			    session.name,
			    session.id,
			    session.turn,
			    agent.max_turns()
			);
			if let Some(s) = &last_summary {
			    println!(
				"{}",
				turn_footer(
				    session.turn,
				    s.tool_calls,
				    s.usage.input_tokens,
				    s.usage.output_tokens,
				    agent.max_turns(),
				)
			    );
			} else {
			    println!("No TurnSummary");
			}
			continue;
		    }
		    _ => {}
		}

		// Handle `/file <PATH>`: read the file's contents relative to
		// the working directory (or absolute) and use it as the prompt.
		// Only a single line can be typed at the REPL prompt, so this
		// lets multi-line content (a prompt, a plan, code) be loaded
		// from disk and sent to the model in one go.
		if let Some(rest) = line.strip_prefix("/file ") {
		    let path = rest.trim();
		    if path.is_empty() {
			eprintln!("/file requires a path");
			continue;
		    }
		    let content = match read_prompt_file(working_dir, path) {
			Ok(c) => c,
			Err(e) => {
			    eprintln!("error reading '{path}': {e}");
			    continue;
			}
		    };
		    if content.trim().is_empty() {
			eprintln!("/file '{path}' is empty");
			continue;
		    }
		    println!(
			"using contents of '{}' ({}, {} bytes) as prompt",
			path,
			cwd.display(),
			content.len()
		    );
		    last_summary =
			run_turn(session, &mut agent, provider, model_name, &content).await;
		    continue;
		}

		last_summary = run_turn(session, &mut agent, provider, model_name, &line).await;
	    }
	    Ok(Signal::CtrlC) | Ok(Signal::ExternalBreak(_)) => continue,
	    Ok(Signal::CtrlD) => break,
	    Ok(_) => continue,
	    Err(e) => {
		eprintln!("readline error: {e}");
		break;
	    }
	}
    }

    // Sync history to disk before shutting down.
    if let Err(e) = editor.sync_history() {
	eprintln!("warning: failed to sync history: {e}");
    }
    Ok(())
}

/// Run a single turn with the given prompt and stream the model's output.
async fn run_turn<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    agent: &mut Agent<M>,
    provider: &str,
    model_name: &str,
    prompt: &str,
) -> Option<TurnSummary> {
    match session
	.run_streaming(agent, provider, model_name, prompt)
	.await
    {
	Ok(mut rx) => {
	    while let Some(event) = rx.recv().await {
		match event {
		    StreamEvent::TextDelta { text } => print_coloured!("{text}"),
		    StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
		    StreamEvent::ToolCallArgs { .. } => {}
		    StreamEvent::ToolCallReady { .. } => {}
		    StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
		    StreamEvent::TurnComplete { summary } => {
			println!();
			println_coloured!(
			    "[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
			    session.turn,
			    summary.tool_calls,
			    summary.usage.input_tokens,
			    summary.usage.output_tokens,
			    agent.max_turns()
			);
			// TODO: Do I need this `clone`?
			agent.set_history(summary.final_history.clone());
			return Some(summary);
		    }
		    StreamEvent::Error { message } => {
			eprintln!();
			eprintln!("error: {message}");
			return None;
		    }
		}
	    }
	    None
	}
	Err(e) => {
	    eprintln!("error: {e}");
	    None
	}
    }
}

//! Session management: named, persistent conversation containers with
//! append-only JSONL event logs.
//!
//! A [`Session`] holds the on-disk state (metadata, event log, lock) for a
//! named conversation. It does not own an [`Agent`]; the caller passes the
//! agent to [`Session::run`], which wraps the agent loop with full logging.
//!
//! [`SessionManager`] owns the working directory and handles creation,
//! opening, and closing of sessions.
//!
//! [`Agent`]: crate::agent::Agent

pub mod lock;
pub mod log;

use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use chrono::Utc;
use rig::completion::message::{ToolCall, ToolFunction};
use rig::completion::{AssistantContent, CompletionModel, Message};
use serde::Serialize;
use tokio::sync::mpsc;
use uuid::Uuid;

use self::lock::SessionGuard;
use self::log::{ErrorStage, LogEntry, LogWriter, ToolCallData, UsageData};
use crate::agent::{Agent, StreamEvent, TurnSummary};
use crate::error::AgentError;

/// Errors produced by session operations.
#[derive(Debug)]
pub enum SessionError {
    /// The session name is reserved and cannot be created manually.
    ReservedName(String),
    /// A session with this name already exists.
    AlreadyExists(String),
    /// The requested session was not found.
    NotFound(String),
    /// The session is locked by another process.
    Locked(String),
    /// An I/O error occurred.
    Io(io::Error),
    /// A JSON (de)serialization error occurred.
    Json(serde_json::Error),
}

impl std::fmt::Display for SessionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SessionError::ReservedName(name) => {
                write!(f, "'{name}' is reserved and cannot be created manually")
            }
            SessionError::AlreadyExists(name) => {
                write!(f, "session '{name}' already exists")
            }
            SessionError::NotFound(name) => {
                write!(
                    f,
                    "session '{name}' not found — use --new-session to create it"
                )
            }
            SessionError::Locked(name) => {
                write!(f, "session '{name}' is locked by another process")
            }
            SessionError::Io(e) => write!(f, "io error: {e}"),
            SessionError::Json(e) => write!(f, "json error: {e}"),
        }
    }
}

impl std::error::Error for SessionError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SessionError::Io(e) => Some(e),
            SessionError::Json(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for SessionError {
    fn from(e: io::Error) -> Self {
        SessionError::Io(e)
    }
}

impl From<serde_json::Error> for SessionError {
    fn from(e: serde_json::Error) -> Self {
        SessionError::Json(e)
    }
}

impl From<AgentError> for SessionError {
    fn from(e: AgentError) -> Self {
        SessionError::Io(io::Error::other(e.to_string()))
    }
}

/// Manages the set of active sessions within a working directory.
#[derive(Debug)]
pub struct SessionManager {
    working_dir: PathBuf,
    sessions: HashMap<String, Session>,
}

impl SessionManager {
    /// Create a new manager. `working_dir` is resolved relative to the
    /// process cwd at startup (the caller must resolve it).
    pub fn new(working_dir: impl Into<PathBuf>) -> Self {
        Self {
            working_dir: working_dir.into(),
            sessions: HashMap::new(),
        }
    }

    /// Path to the sessions directory: `<working_dir>/sessions/`.
    pub fn sessions_dir(&self) -> PathBuf {
        self.working_dir.join("sessions")
    }

    /// Check whether a session exists (by name) on disk.
    pub fn exists(&self, name: &str) -> bool {
        self.session_dir(name).exists()
    }

    /// List session names found on disk.
    pub fn list(&self) -> io::Result<Vec<String>> {
        let dir = self.sessions_dir();
        if !dir.exists() {
            return Ok(Vec::new());
        }
        let mut names = Vec::new();
        for entry in fs::read_dir(&dir)? {
            let entry = entry?;
            if entry.file_type()?.is_dir()
                && let Some(name) = entry.file_name().to_str()
            {
                names.push(name.to_string());
            }
        }
        names.sort();
        Ok(names)
    }

    /// Create a new session. Fails if the name is reserved or already exists.
    pub fn create(
        &mut self,
        name: &str,
        model: &str,
        system_prompt: &str,
    ) -> Result<&mut Session, SessionError> {
        if name == "default-session" {
            return Err(SessionError::ReservedName(name.into()));
        }
        if self.exists(name) {
            return Err(SessionError::AlreadyExists(name.into()));
        }
        let session = Session::create(&self.sessions_dir(), name, model, system_prompt)?;
        self.sessions.insert(name.to_string(), session);
        Ok(self.sessions.get_mut(name).expect("just inserted"))
    }

    /// Create the reserved auto session (`default-session`).
    ///
    /// Only the CLI's implicit auto-create path may call this; `create`
    /// rejects reserved names so users cannot claim them explicitly.
    pub fn create_default(
        &mut self,
        model: &str,
        system_prompt: &str,
    ) -> Result<&mut Session, SessionError> {
        if self.exists("default-session") {
            return Err(SessionError::AlreadyExists("default-session".into()));
        }
        let session = Session::create(
            &self.sessions_dir(),
            "default-session",
            model,
            system_prompt,
        )?;
        self.sessions.insert("default-session".to_string(), session);
        Ok(self
            .sessions
            .get_mut("default-session")
            .expect("just inserted"))
    }

    /// Open an existing session. Fails if it doesn't exist or is locked.
    pub fn open(&mut self, name: &str) -> Result<&mut Session, SessionError> {
        if self.sessions.contains_key(name) {
            return self
                .sessions
                .get_mut(name)
                .ok_or_else(|| SessionError::NotFound(name.into()));
        }
        if !self.exists(name) {
            return Err(SessionError::NotFound(name.into()));
        }
        let session = Session::open(&self.sessions_dir(), name)?;
        self.sessions.insert(name.to_string(), session);
        Ok(self.sessions.get_mut(name).expect("just inserted"))
    }

    /// Close a session: writes `session_closed`, flushes the log, and
    /// releases the filesystem lock.
    pub fn close(&mut self, name: &str) -> Result<(), SessionError> {
        let mut session = self
            .sessions
            .remove(name)
            .ok_or_else(|| SessionError::NotFound(name.into()))?;
        let turn = session.turn;
        session.log_entry(&LogEntry::session_closed(
            Utc::now(),
            turn,
            session.id.to_string(),
            session.name.clone(),
        ))?;
        drop(session); // releases lock
        Ok(())
    }

    /// Path to a specific session directory.
    fn session_dir(&self, name: &str) -> PathBuf {
        self.sessions_dir().join(name)
    }
}

/// A named, persistent session that holds on-disk state and a log writer.
///
/// Created and managed via [`SessionManager`]; not constructed directly.
/// Call [`Session::run`] with an agent to execute a turn with full logging.
#[derive(Debug)]
pub struct Session {
    /// Unique identifier for this session (stable across restarts).
    pub id: Uuid,
    /// Human-readable session name.
    pub name: String,
    /// When the session was first created.
    pub created_at: chrono::DateTime<Utc>,
    /// Model name in use.
    pub model: String,
    /// Current turn number (monotonically increasing).
    pub turn: u64,

    /// Path to the session directory on disk.
    root: PathBuf,
    /// Append-only event log writer.
    log: LogWriter,
    /// Filesystem lock held for the lifetime of this session.
    _guard: SessionGuard,
}

impl Session {
    /// Path to the session directory on disk.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Create a new session on disk. Internal — use `SessionManager::create`.
    fn create(
        sessions_dir: &Path,
        name: &str,
        model: &str,
        system_prompt: &str,
    ) -> Result<Self, SessionError> {
        let dir = sessions_dir.join(name);
        fs::create_dir_all(&dir)?;

        let guard = SessionGuard::acquire(&dir).map_err(|_| SessionError::Locked(name.into()))?;

        let id = Uuid::new_v4();
        let created_at = Utc::now();

        // Write session.json.
        let meta = serde_json::json!({
            "id": id.to_string(),
            "name": name,
            "created_at": created_at.to_rfc3339(),
            "model": model,
            "system_prompt": system_prompt,
        });
        fs::write(
            dir.join("session.json"),
            serde_json::to_string_pretty(&meta)?,
        )?;

        // Open the event log.
        let log_path = dir.join("events.jsonl");
        let mut log = LogWriter::open(&log_path)?;

        // Log creation and first open.
        let now = Utc::now();
        log.write_entry(&LogEntry::session_created(
            now,
            0,
            id.to_string(),
            name.to_string(),
            model.to_string(),
            system_prompt.to_string(),
        ))?;
        log.write_entry(&LogEntry::session_opened(
            now,
            0,
            id.to_string(),
            name.to_string(),
        ))?;

        Ok(Self {
            id,
            name: name.to_string(),
            created_at,
            model: model.to_string(),
            turn: 0,
            root: dir,
            log,
            _guard: guard,
        })
    }

    /// Open an existing session. Internal — use `SessionManager::open`.
    fn open(sessions_dir: &Path, name: &str) -> Result<Self, SessionError> {
        let dir = sessions_dir.join(name);
        if !dir.exists() {
            return Err(SessionError::NotFound(name.into()));
        }

        let guard = SessionGuard::acquire(&dir).map_err(|_| SessionError::Locked(name.into()))?;

        // Read session.json.
        let meta_path = dir.join("session.json");
        let meta_bytes = fs::read(&meta_path)?;
        let meta: serde_json::Value = serde_json::from_slice(&meta_bytes)?;
        let id: Uuid = meta["id"]
            .as_str()
            .and_then(|s| s.parse().ok())
            .unwrap_or_else(Uuid::new_v4);
        let created_at: chrono::DateTime<Utc> = meta["created_at"]
            .as_str()
            .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
            .map(|dt| dt.with_timezone(&Utc))
            .unwrap_or_else(Utc::now);
        let model = meta["model"].as_str().unwrap_or("unknown").to_string();

        let log_path = dir.join("events.jsonl");
        let mut log = LogWriter::open(&log_path)?;

        let now = Utc::now();
        log.write_entry(&LogEntry::session_opened(
            now,
            0,
            id.to_string(),
            name.to_string(),
        ))?;

        Ok(Self {
            id,
            name: name.to_string(),
            created_at,
            model,
            turn: 0,
            root: dir,
            log,
            _guard: guard,
        })
    }

    /// Run one user turn with full logging.
    ///
    /// Wraps the agent loop: for each model call and tool execution, an
    /// event is written to the session log. Returns the same `TurnSummary`
    /// as [`Agent::run`].
    pub async fn run<M: CompletionModel>(
        &mut self,
        agent: &mut Agent<M>,
        provider: &str,
        model_name: &str,
        user_input: &str,
    ) -> Result<TurnSummary, AgentError> {
        self.turn += 1;

        // Log user input.
        self.log_entry(&LogEntry::user_input(
            Utc::now(),
            self.turn,
            user_input.to_string(),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;

        let mut turn_messages: Vec<Message> = Vec::new();
        let mut tool_calls_total = 0usize;
        let mut usage_total = rig::completion::Usage::new();

        for _ in 0..agent.max_turns() {
            // Build and log the prompt.
            let tools = agent.tool_definitions();
            let messages_json = self.messages_for_log(
                agent.system_prompt(),
                agent.history(),
                &turn_messages,
                user_input,
            )?;
            let tools_json =
                serde_json::to_value(&tools).map_err(|e| AgentError::Rig(e.to_string()))?;
            self.log_entry(&LogEntry::llm_prompt(
                Utc::now(),
                self.turn,
                provider.to_string(),
                model_name.to_string(),
                messages_json,
                tools_json,
            ))
            .map_err(|e| AgentError::Rig(e.to_string()))?;

            // Call the model.
            let response = agent.single_completion(user_input, &turn_messages).await?;
            usage_total += response.usage;

            // Extract content from the response.
            let mut text_parts: Vec<rig::completion::message::Text> = Vec::new();
            let mut reasoning_parts: Vec<String> = Vec::new();
            let mut tool_calls: Vec<ToolCall> = Vec::new();
            for content in response.choice.iter() {
                match content {
                    AssistantContent::Text(t) => text_parts.push(t.clone()),
                    AssistantContent::ToolCall(call) => tool_calls.push(call.clone()),
                    AssistantContent::Reasoning(r) => {
                        reasoning_parts.push(format!("{r:?}"));
                    }
                    AssistantContent::Image(_) => {}
                }
            }

            // Log the response.
            let response_text = if text_parts.is_empty() {
                None
            } else {
                Some(
                    text_parts
                        .iter()
                        .map(|t| t.text())
                        .collect::<Vec<_>>()
                        .join("\n"),
                )
            };
            let response_reasoning = if reasoning_parts.is_empty() {
                None
            } else {
                Some(reasoning_parts.join("\n"))
            };
            let response_tool_calls: Option<Vec<ToolCallData>> = if tool_calls.is_empty() {
                None
            } else {
                Some(
                    tool_calls
                        .iter()
                        .map(|c| ToolCallData {
                            id: c.id.clone(),
                            name: c.function.name.clone(),
                            arguments: c.function.arguments.clone(),
                        })
                        .collect(),
                )
            };
            self.log_entry(&LogEntry::llm_response(
                Utc::now(),
                self.turn,
                response.message_id.clone(),
                response_text.clone(),
                response_reasoning,
                response_tool_calls.clone(),
                UsageData {
                    input_tokens: response.usage.input_tokens as u32,
                    output_tokens: response.usage.output_tokens as u32,
                },
            ))
            .map_err(|e| AgentError::Rig(e.to_string()))?;

            // No tool calls: turn complete.
            if tool_calls.is_empty() {
                let text = response_text.unwrap_or_default();
                turn_messages.push(Message::assistant(text.clone()));
                agent.commit_turn(user_input, turn_messages);

                self.log_entry(&LogEntry::turn_complete(
                    Utc::now(),
                    self.turn,
                    text.clone(),
                    tool_calls_total,
                ))
                .map_err(|e| AgentError::Rig(e.to_string()))?;

                return Ok(TurnSummary {
                    text,
                    tool_calls: tool_calls_total,
                    usage: usage_total,
                    final_history: agent.history().to_vec(),
                });
            }

            // Record the assistant message and execute tools.
            let mut contents: Vec<AssistantContent> =
                text_parts.into_iter().map(AssistantContent::Text).collect();
            contents.extend(tool_calls.iter().cloned().map(AssistantContent::ToolCall));
            turn_messages.push(Message::Assistant {
                id: response.message_id,
                content: rig::OneOrMany::from_iter_optional(contents)
                    .expect("assistant message has at least one tool call"),
            });

            for call in &tool_calls {
                let tool_args = call.function.arguments.clone();
                match agent.execute_tool(call).await {
                    Ok(output) => {
                        tool_calls_total += 1;
                        self.log_entry(&LogEntry::tool_execution(
                            Utc::now(),
                            self.turn,
                            call.id.clone(),
                            call.call_id.clone().unwrap_or_else(|| call.id.clone()),
                            call.function.name.clone(),
                            tool_args,
                            output.clone(),
                        ))
                        .map_err(|e| AgentError::Rig(e.to_string()))?;
                        turn_messages.push(Message::tool_result_with_call_id(
                            call.id.clone(),
                            call.call_id.clone(),
                            output,
                        ));
                    }
                    Err(e) => {
                        // Log error and bail.
                        self.log_entry(&LogEntry::error(
                            Utc::now(),
                            self.turn,
                            ErrorStage::ToolExecution,
                            e.to_string(),
                        ))
                        .map_err(|se| AgentError::Rig(se.to_string()))?;
                        agent.commit_turn(user_input, turn_messages);
                        return Err(e);
                    }
                }
            }
        }

        // Max turns exceeded.
        self.log_entry(&LogEntry::error(
            Utc::now(),
            self.turn,
            ErrorStage::LlmCall,
            format!("exceeded maximum of {} model turns", agent.max_turns()),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;
        agent.commit_turn(user_input, turn_messages);
        Err(AgentError::MaxTurns {
            turns: agent.max_turns(),
        })
    }

    /// Run one user turn with streaming output and full logging.
    ///
    /// Like [`run`], but model output arrives token-by-token through a
    /// channel. The caller reads [`StreamEvent`]s while the agent loop
    /// runs concurrently. Session lifecycle and tool execution events
    /// are logged from the stream.
    ///
    /// [`StreamEvent`]: crate::agent::StreamEvent
    pub async fn run_streaming<M: CompletionModel + 'static>(
        &mut self,
        agent: &mut Agent<M>,
        _provider: &str,
        _model_name: &str,
        user_input: &str,
    ) -> Result<mpsc::Receiver<StreamEvent>, AgentError>
    where
        M::StreamingResponse: Send,
    {
        self.turn += 1;

        // Log user input.
        self.log_entry(&LogEntry::user_input(
            Utc::now(),
            self.turn,
            user_input.to_string(),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;

        let mut agent_rx = agent
            .run_streaming(user_input)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        let (tx, rx) = mpsc::channel(32);

        // Spawn a task that reads from the agent stream, logs tool
        // executions and turn completion, and forwards events to the
        // session's own channel.
        let turn = self.turn;
        let log_path = self.events_path();

        tokio::spawn(async move {
            // Re-open the log for appending from this task.
            let mut log_writer =
                LogWriter::open(&log_path).expect("re-open session log for streaming");

            let mut tool_calls_total: usize = 0;
            // Track tool arguments captured at ToolCallReady so the
            // tool_execution entry can log the real values (not a
            // placeholder).
            let mut pending_args: HashMap<String, serde_json::Value> = HashMap::new();

            while let Some(event) = agent_rx.recv().await {
                match &event {
                    StreamEvent::ToolCallReady {
                        id,
                        name: _,
                        arguments,
                    } => {
                        pending_args.insert(id.clone(), arguments.clone());
                    }
                    StreamEvent::ToolResult {
                        id,
                        name,
                        result,
                        result_preview: _,
                    } => {
                        tool_calls_total += 1;
                        let args = pending_args.remove(id).unwrap_or(serde_json::Value::Null);
                        // Log the real arguments and full result.
                        let _ = log_writer.write_entry(&LogEntry::tool_execution(
                            Utc::now(),
                            turn,
                            id.clone(),
                            id.clone(), // call_id same as tool_call_id (simplified)
                            name.clone(),
                            args,
                            result.clone(),
                        ));
                    }
                    StreamEvent::TurnComplete { summary } => {
                        let _ = log_writer.write_entry(&LogEntry::turn_complete(
                            Utc::now(),
                            turn,
                            summary.text.clone(),
                            tool_calls_total,
                        ));
                        // Note: caller must call agent.set_history(summary.final_history)
                        // after reading TurnComplete.
                    }
                    StreamEvent::Error { message } => {
                        let _ = log_writer.write_entry(&LogEntry::error(
                            Utc::now(),
                            turn,
                            ErrorStage::LlmCall,
                            message.clone(),
                        ));
                    }
                    _ => {}
                }
                let _ = tx.send(event).await;
            }
        });

        Ok(rx)
    }

    /// Build a JSON representation of the messages sent to the model,
    /// for inclusion in the `llm_prompt` log entry.
    fn messages_for_log(
        &self,
        system_prompt: &str,
        history: &[Message],
        turn_messages: &[Message],
        user_input: &str,
    ) -> Result<serde_json::Value, AgentError> {
        #[derive(Serialize)]
        struct LogMessage {
            role: String,
            content: serde_json::Value,
        }

        let mut msgs: Vec<LogMessage> = Vec::new();

        // System preamble.
        msgs.push(LogMessage {
            role: "system".into(),
            content: serde_json::Value::String(system_prompt.to_string()),
        });

        // Serialize each message via serde.
        fn msg_to_value(msg: &Message) -> Result<LogMessage, AgentError> {
            let v = serde_json::to_value(msg).map_err(|e| AgentError::Rig(e.to_string()))?;
            let role = v["role"].as_str().unwrap_or("unknown").to_string();
            Ok(LogMessage {
                role,
                content: v["content"].clone(),
            })
        }

        for m in history.iter().chain(turn_messages.iter()) {
            msgs.push(msg_to_value(m)?);
        }
        // Current user message.
        msgs.push(LogMessage {
            role: "user".into(),
            content: serde_json::Value::String(user_input.to_string()),
        });

        serde_json::to_value(&msgs).map_err(|e| AgentError::Rig(e.to_string()))
    }

    /// Append an entry to the event log.
    pub fn log_entry(&mut self, entry: &LogEntry) -> Result<(), SessionError> {
        self.log.write_entry(entry)?;
        Ok(())
    }

    /// Read the full session metadata from `session.json`.
    pub fn read_meta(&self) -> Result<serde_json::Value, SessionError> {
        let meta_path = self.root.join("session.json");
        let bytes = fs::read(&meta_path)?;
        let value: serde_json::Value = serde_json::from_slice(&bytes)?;
        Ok(value)
    }

    /// Path to the events log file.
    pub fn events_path(&self) -> PathBuf {
        self.root.join("events.jsonl")
    }

    /// Path to the session metadata file.
    pub fn meta_path(&self) -> PathBuf {
        self.root.join("session.json")
    }

    /// Reconstruct agent message history from the event log.
    ///
    /// Walks the log, builds `Message` values for each completed turn, and
    /// stops at the last `turn_complete` or `error` boundary. Partial turns
    /// (events after the last complete turn without a close) are dropped.
    ///
    /// Lifecycle events (`session_created`, `session_opened`, etc.) and
    /// `llm_prompt` entries are skipped — they're not needed for history
    /// reconstruction.
    pub fn replay_history(&self) -> Result<Vec<Message>, SessionError> {
        let entries = self.events()?;
        let mut messages: Vec<Message> = Vec::new();
        let mut safe_len: usize = 0;
        // Track whether the last assistant message had tool calls.
        let mut last_had_tool_calls = false;

        for entry in &entries {
            match entry {
                LogEntry::UserInput { data, .. } => {
                    messages.push(Message::user(data.text.clone()));
                    last_had_tool_calls = false;
                }
                LogEntry::LlmResponse { data, .. } => {
                    if let Some(ref tcs) = data.tool_calls {
                        let contents: Vec<AssistantContent> = tcs
                            .iter()
                            .map(|tc| {
                                AssistantContent::ToolCall(ToolCall::new(
                                    tc.id.clone(),
                                    ToolFunction {
                                        name: tc.name.clone(),
                                        arguments: tc.arguments.clone(),
                                    },
                                ))
                            })
                            .collect();
                        messages.push(Message::Assistant {
                            id: data.message_id.clone(),
                            content: rig::OneOrMany::from_iter_optional(contents)
                                .expect("assistant message has at least one tool call"),
                        });
                        last_had_tool_calls = true;
                    } else if let Some(ref text) = data.text {
                        messages.push(Message::assistant(text.clone()));
                        last_had_tool_calls = false;
                    }
                }
                LogEntry::ToolExecution { data, .. } => {
                    // Streaming sessions may lack llm_response entries. If
                    // the last assistant had no tool calls, synthesize one
                    // for this specific tool execution.
                    let was_synthetic = !last_had_tool_calls;
                    if was_synthetic {
                        let tc = ToolCall::new(
                            data.tool_call_id.clone(),
                            ToolFunction {
                                name: data.name.clone(),
                                arguments: data.arguments.clone(),
                            },
                        );
                        messages.push(Message::Assistant {
                            id: None,
                            content: rig::OneOrMany::one(AssistantContent::ToolCall(tc)),
                        });
                        last_had_tool_calls = true;
                    }
                    let call_id = if data.call_id.is_empty() {
                        data.tool_call_id.clone()
                    } else {
                        data.call_id.clone()
                    };
                    messages.push(Message::tool_result_with_call_id(
                        data.tool_call_id.clone(),
                        Some(call_id),
                        data.result.clone(),
                    ));
                    // If we synthesized the assistant, reset so the
                    // next tool_exec gets its own assistant too.
                    if was_synthetic {
                        last_had_tool_calls = false;
                    }
                }
                LogEntry::TurnComplete { .. } | LogEntry::Error { .. } => {
                    // End of a completed turn — mark all accumulated
                    // messages as safe.
                    safe_len = messages.len();
                }
                // Skip lifecycle and prompt entries.
                LogEntry::SessionCreated { .. }
                | LogEntry::SessionOpened { .. }
                | LogEntry::SessionClosed { .. }
                | LogEntry::LlmPrompt { .. } => {}
            }
        }

        // Truncate to the last complete turn boundary.
        messages.truncate(safe_len);
        Ok(messages)
    }

    // --- Derived property accessors (Step 4) ---

    /// Parse all events from the log file and return them.
    pub fn events(&self) -> Result<Vec<LogEntry>, SessionError> {
        let path = self.events_path();
        if !path.exists() {
            return Ok(Vec::new());
        }
        let contents = fs::read_to_string(&path)?;
        let mut entries = Vec::new();
        for line in contents.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let entry: LogEntry = serde_json::from_str(line).map_err(SessionError::Json)?;
            entries.push(entry);
        }
        Ok(entries)
    }

    /// Compute cumulative token usage from all `llm_response` events.
    pub fn cumulative_usage(&self) -> Result<(u64, u64), SessionError> {
        let mut total_in: u64 = 0;
        let mut total_out: u64 = 0;
        for entry in self.events()? {
            if let LogEntry::LlmResponse { data, .. } = &entry {
                total_in += data.usage.input_tokens as u64;
                total_out += data.usage.output_tokens as u64;
            }
        }
        Ok((total_in, total_out))
    }

    /// Timestamp of the most recent `session_opened` event.
    pub fn last_opened_at(&self) -> Result<Option<chrono::DateTime<Utc>>, SessionError> {
        let events = self.events()?;
        let last = events
            .iter()
            .rev()
            .find(|e| matches!(e, LogEntry::SessionOpened { .. }));
        Ok(last.map(|e| e.ts()))
    }

    /// Total turns from the most recent `turn_complete` event.
    pub fn total_turns(&self) -> Result<u64, SessionError> {
        let events = self.events()?;
        let last = events
            .iter()
            .rev()
            .find(|e| matches!(e, LogEntry::TurnComplete { .. }));
        Ok(last.map(|e| e.turn()).unwrap_or(0))
    }

    /// Per-call model latencies computed from prompt/response timestamp
    /// pairs. Returns a vector of (ts, latency_ms) for each completed call.
    pub fn latencies(&self) -> Result<Vec<(chrono::DateTime<Utc>, i64)>, SessionError> {
        let events = self.events()?;
        let mut latencies = Vec::new();
        let mut pending_prompt_ts: Option<chrono::DateTime<Utc>> = None;

        for entry in &events {
            match entry {
                LogEntry::LlmPrompt { ts, .. } => {
                    pending_prompt_ts = Some(*ts);
                }
                LogEntry::LlmResponse { ts, .. } => {
                    if let Some(prompt_ts) = pending_prompt_ts.take() {
                        let latency_ms = (*ts - prompt_ts).num_milliseconds();
                        latencies.push((*ts, latency_ms));
                    }
                }
                _ => {}
            }
        }

        Ok(latencies)
    }
}

